{
  "status": "NEEDS_IMPROVEMENT",
  "core_findings": [
    "Training separation varies substantially: negatives outrank positives at 10.04% of Electronics positions and 8.76% of Industrial positions, versus 0.78% for CDs. Embedding alignment scores of 0.5066–0.5246 do not indicate directional collapse or establish recommendation diversity.",
    "Measured ModelView readout and causality controls pass, but exported-predictor parity remains unverified and manifest writing failed. History deletions generally worsen in-sample rankings; Industrial estimates are less conclusive."
  ],
  "key_implications": [
    "The model uses history information on measured training prefixes, with stronger evidence of recent-history dependence for CDs.",
    "Training margins identify weaker separation in Electronics and Industrial, but their scale depends on embedding norms and does not measure validation HR@10.",
    "Sensitivity results do not establish generalization or improvement; bootstrap intervals exclude training-seed and candidate-sampling uncertainty."
  ],
  "evidence": {
    "headline_metrics": {
      "Electronics:pos_neg_margin_p10": -0.0106,
      "Industrial_and_Scientific:pos_neg_neg_beats_pos_rate": 0.0876,
      "CDs_and_Vinyl:pos_neg_neg_beats_pos_rate": 0.0078,
      "CDs_and_Vinyl:recent_minus_older_delete_rank_delta": 4.046875
    },
    "brief_metric_read": {
      "Electronics:pos_neg_margin_p10": "Lower training-margin tail reaches below zero.",
      "Industrial_and_Scientific:pos_neg_neg_beats_pos_rate": "8.76% of sampled training positions rank the negative higher.",
      "CDs_and_Vinyl:pos_neg_neg_beats_pos_rate": "0.78% of sampled training positions rank the negative higher.",
      "CDs_and_Vinyl:recent_minus_older_delete_rank_delta": "Recent deletion worsens rank more; paired-user 95% interval [0.90625, 8.46875]."
    }
  }
